import { sql } from 'drizzle-orm';
import { customType, timestamp, uuid } from 'drizzle-orm/pg-core';

/**
 * The column shapes every module's tables are built from.
 *
 * These exist so that "how we store an id", "how we store money" and "how we
 * store a place" are decided once. Eleven modules each making their own call
 * is how you end up with two timestamp conventions and a fee column that is a
 * float in one table and a bigint in another.
 */

/**
 * Primary key: a v7 UUID, generated by Postgres.
 *
 * v7 rather than v4 because it is time-ordered. A random v4 scatters inserts
 * across the whole B-tree, so every insert dirties a different page; v7 keys
 * sort by creation time, which keeps inserts at the right edge of the index.
 *
 * Ordered **to the millisecond**, not strictly monotonic: two ids generated in
 * the same millisecond sort arbitrarily, because v7 does not carry a counter.
 * That is fine for the clustering benefit, but it means `ORDER BY id` is an
 * approximation of `ORDER BY created_at`, not a replacement — a messages list
 * should still order by the timestamp.
 *
 * `gen_random_uuid_v7()` is native in Postgres 18. The image is Postgres 16, so
 * `drizzle/0000_uuid_v7.sql` installs a plpgsql shim with interchangeable
 * output. Delete it when the image moves to 18.
 */
export const id = () =>
  uuid('id')
    .primaryKey()
    .default(sql`gen_random_uuid_v7()`);

/** A reference to another module's row. Never a foreign key — see below. */
export const reference = (name: string) => uuid(name);

/**
 * `created_at` and `updated_at`, both UTC with a timezone.
 *
 * `withTimezone: true` is not optional: `timestamp` without it stores a wall
 * clock with no zone, so a server in a different region reads back a different
 * instant. The app shows Lagos time (`web/src/lib/date.ts` pins
 * `Africa/Lagos`), but it stores absolute instants and converts at the edge.
 *
 * `updated_at` defaults rather than being touched by a trigger, so the helper
 * is honest about what it does: a repo that forgets to set it on update will
 * leave a stale value, which is visible in tests.
 */
export const timestamps = () => ({
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
});

/**
 * Integer micro-USDC (6 decimals), as a JS `bigint`.
 *
 * `bigint` because micro-USDC exceeds `Number.MAX_SAFE_INTEGER` at about
 * 9 billion USDC — far away, but the failure mode when it arrives is silent
 * rounding of someone's money, and `numeric` with a JS float is wrong
 * immediately rather than eventually.
 *
 * Postgres `bigint` arrives from `pg` as a **string**, not a number, precisely
 * so the driver does not lose precision. The `fromDriver` below is what turns
 * it back into a `bigint` — without it a repo gets `"31500000"` and the first
 * `+` in any fee calculation concatenates instead of adding (CLAUDE.md rule 4
 * says the maths lives in `domain/`, which is where that would surface).
 */
export const usdc = customType<{ data: bigint; driverData: string }>({
  dataType: () => 'bigint',
  fromDriver: (value) => BigInt(value),
  toDriver: (value) => value.toString(),
});

/**
 * A PostGIS `geography(Point, 4326)` — a place on the Earth, in WGS 84.
 *
 * `geography` rather than `geometry`: geometry does planar maths, so a distance
 * query would be in degrees and wrong by a factor that grows with latitude.
 * Geography does the spherical calculation and `ST_DWithin` returns metres,
 * which is what discovery search needs.
 *
 * Stored as `{ lon, lat }` — **longitude first**, which is PostGIS's order and
 * the reverse of how people say it. Getting it backwards puts Lagos in the
 * Indian Ocean, so the type names the fields rather than taking a tuple.
 *
 * What is stored is a base location, never a live position: architecture.md §8
 * keeps live location in Redis for the duration of a session and deletes it
 * afterwards.
 */
export interface Point {
  readonly lon: number;
  readonly lat: number;
}

export const geographyPoint = customType<{ data: Point; driverData: string }>({
  dataType: () => 'geography(Point, 4326)',
  // PostGIS returns WKB hex. Selecting the raw column and parsing that here
  // would mean re-implementing WKB, so repos select
  // `ST_X(col::geometry), ST_Y(col::geometry)` when they need the numbers —
  // this type is for writing and for the index.
  fromDriver: (value) => {
    const match = /POINT\(([-\d.]+) ([-\d.]+)\)/.exec(value);
    if (!match) throw new Error(`Unrecognised point from the driver: ${value}`);
    return { lon: Number(match[1]), lat: Number(match[2]) };
  },
  toDriver: (value) => `SRID=4326;POINT(${String(value.lon)} ${String(value.lat)})`,
});

/**
 * No cross-module foreign keys.
 *
 * A module owns its own tables (CLAUDE.md rule 1), and architecture.md §3 says
 * modules should stay splittable into services. A foreign key from
 * `booking.bookings` to `auth.users` is a database-level coupling that cannot
 * survive that split — and it enforces at the wrong layer anyway, since the
 * rule being protected is "this user exists", which only the auth module can
 * answer.
 *
 * Within one module, use real foreign keys. Across modules, use `reference()`
 * and call the other module's service.
 */
